package com.example.leetcodetrainer.curriculum.domain;
import jakarta.persistence.*; import java.util.*;
@Entity @Table(name="mode_skill_requirement") public class ModeSkillRequirement { @Id private UUID id; @Enumerated(EnumType.STRING) private LearningMode learningMode; @Column(name="skill_definition_id") private UUID skillDefinitionId; private int displayOrder; @Enumerated(EnumType.STRING) private RequirementApplicability applicability; private boolean assistanceAllowed,stopOnFailure,completionRequired; protected ModeSkillRequirement(){} public LearningMode getLearningMode(){return learningMode;} public UUID getSkillDefinitionId(){return skillDefinitionId;} public int getDisplayOrder(){return displayOrder;} public RequirementApplicability getApplicability(){return applicability;} public boolean isAssistanceAllowed(){return assistanceAllowed;} public boolean isStopOnFailure(){return stopOnFailure;} public boolean isCompletionRequired(){return completionRequired;} }
